// Normalize RemoteOK jobs
const raw = $input.first().json;
const jobs = [];

// RemoteOK returns array, first item is metadata so skip it
const listings = Array.isArray(raw) ? raw.slice(1) : [];

for (const job of listings.slice(0, 30)) {
  if (!job.position || !job.company) continue;

  jobs.push({
    source: 'RemoteOK',
    title: job.position || '',
    company: job.company || '',
    location: job.location || 'Remote',
    salary: job.salary || '',
    description: (job.description || '').slice(0, 1500),
    tags: Array.isArray(job.tags) ? job.tags.join(', ') : '',
    url: job.url || `https://remoteok.com/l/${job.id}`,
    posted: job.date || ''
  });
}

return jobs.map(j => ({ json: j }));

// Normalize Jobicy jobs
const raw = $input.first().json;
const jobs = [];

const listings = raw.jobs || [];

for (const job of listings.slice(0, 30)) {
  jobs.push({
    source: 'Jobicy',
    title: job.jobTitle || '',
    company: job.companyName || '',
    location: job.jobGeo || 'Remote',
    salary: job.annualSalaryMin ? `$${job.annualSalaryMin} - $${job.annualSalaryMax}` : '',
    description: (job.jobDescription || '').slice(0, 1500),
    tags: Array.isArray(job.jobIndustry) ? job.jobIndustry.join(', ') : '',
    url: job.url || '',
    posted: job.pubDate || ''
  });
}

return jobs.map(j => ({ json: j }));

// Merge all jobs from both sources
const allJobs = $input.all().map(item => item.json);

// Basic dedup by title + company
const seen = new Set();
const deduped = [];

for (const job of allJobs) {
  const key = `${job.title?.toLowerCase()}-${job.company?.toLowerCase()}`;
  if (!seen.has(key) && job.title && job.company) {
    seen.add(key);
    deduped.push(job);
  }
}

// Pre-filter: drop obvious mismatches before hitting AI
const titleKeywords = [
  'ai', 'automation', 'operations', 'creative', 'technologist',
  'learning', 'instructional', 'content', 'product', 'engineer',
  'designer', 'developer', 'advocate', 'curriculum', 'workflow',
  'no-code', 'low-code', 'prompt', 'narrative'
];

const dealbreakers = ['staffing', 'commission only', 'relocation', 'on-site only'];

const filtered = deduped.filter(job => {
  const combined = `${job.title} ${job.tags} ${job.description}`.toLowerCase();

  // Must match at least one keyword
  const hasKeyword = titleKeywords.some(kw => combined.includes(kw));

  // Must not hit a dealbreaker
  const hasDealbreaker = dealbreakers.some(db => combined.includes(db));

  return hasKeyword && !hasDealbreaker;
});

console.log(`Total jobs: ${allJobs.length}, After dedup+filter: ${filtered.length}`);

// Limit to 15 for AI analysis to stay within Groq rate limits
return filtered.slice(0, 15).map(j => ({ json: j }));

// Parse Groq response and merge with job data
const groqResponse = $input.first().json;
const rawContent = groqResponse.choices?.[0]?.message?.content || '{}';

let analysis;
try {
  const cleaned = rawContent.replace(/```json|```/g, '').trim();
  analysis = JSON.parse(cleaned);
} catch(e) {
  analysis = {
    match_score: 0,
    match_reason: 'Could not parse — review manually',
    green_flags: '',
    red_flags: 'Parse error',
    salary_estimate: '',
    cover_letter_draft: '',
    recruiter_dm: ''
  };
}

// Get the original job data from the previous item in the chain
// We pass it through via the input item's pairedItem
const jobData = $('Merge + Pre-Filter Jobs').item.json;

return [{ json: { ...jobData, ...analysis } }];

// Filter to only jobs worth showing (match score 6+)
// and sort by match score descending
const allAnalyzed = $input.all().map(i => i.json);

const worthShowing = allAnalyzed
  .filter(job => parseInt(job.match_score) >= 6)
  .sort((a, b) => parseInt(b.match_score) - parseInt(a.match_score));

console.log(`Analyzed: ${allAnalyzed.length}, Worth showing: ${worthShowing.length}`);

if (worthShowing.length === 0) {
  return [{ json: { noResults: true, allJobs: allAnalyzed } }];
}

return [{ json: { jobs: worthShowing, count: worthShowing.length, noResults: false } }];

// Build the HTML email digest
const data = $input.first().json;
const today = new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' });

if (data.noResults) {
  const html = `
    <div style="font-family: Georgia, serif; max-width: 680px; margin: 0 auto; padding: 32px; color: #1a1a1a;">
      <div style="border-bottom: 2px solid #8B7355; padding-bottom: 16px; margin-bottom: 24px;">
        <h1 style="font-size: 24px; margin: 0; color: #8B7355;">☀️ Good Morning, Jasmine</h1>
        <p style="margin: 4px 0 0; color: #666; font-size: 14px;">${today}</p>
      </div>
      <p>No strong matches found today (all jobs scored below 6/10). The pipeline ran clean — check back tomorrow.</p>
      <div style="margin-top: 40px; padding-top: 16px; border-top: 1px solid #eee; font-size: 12px; color: #999;">
        <p>Powered by <strong style="color: #8B7355;">Dynamack Operations</strong> · dynamackops.tiiny.site</p>
      </div>
    </div>`;
  return [{ json: { html, subject: `☀️ Job Digest ${today} — No strong matches today` } }];
}

const jobs = data.jobs;

const scoreColor = (score) => {
  if (score >= 9) return '#2d7a2d';
  if (score >= 7) return '#8B7355';
  return '#666';
};

const jobCards = jobs.map(job => `
  <div style="background: #f9f9f6; border-left: 4px solid ${scoreColor(job.match_score)}; padding: 20px; margin-bottom: 24px; border-radius: 0 8px 8px 0;">
    <div style="display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 8px;">
      <div>
        <h2 style="margin: 0; font-size: 18px; color: #1a1a1a;">${job.title}</h2>
        <p style="margin: 4px 0; color: #555; font-size: 14px;"><strong>${job.company}</strong> · ${job.location} · <em>${job.source}</em></p>
      </div>
      <div style="text-align: right; min-width: 60px;">
        <span style="font-size: 24px; font-weight: bold; color: ${scoreColor(job.match_score)};">${job.match_score}/10</span>
      </div>
    </div>

    ${job.salary_estimate ? `<p style="margin: 0 0 12px; font-size: 13px; color: #444;">💰 ${job.salary_estimate}</p>` : ''}

    <p style="margin: 0 0 8px; font-size: 14px;"><strong>Why it fits:</strong> ${job.match_reason}</p>

    ${job.green_flags ? `<p style="margin: 0 0 8px; font-size: 13px; color: #2d7a2d;">✅ ${job.green_flags}</p>` : ''}
    ${job.red_flags && job.red_flags !== 'none' ? `<p style="margin: 0 0 12px; font-size: 13px; color: #c0392b;">⚠️ ${job.red_flags}</p>` : ''}

    <details style="margin-top: 12px;">
      <summary style="cursor: pointer; font-size: 13px; font-weight: bold; color: #8B7355;">📝 Cover Letter Draft</summary>
      <p style="background: white; padding: 12px; border-radius: 4px; font-size: 13px; margin: 8px 0 0; line-height: 1.6;">${job.cover_letter_draft}</p>
    </details>

    <details style="margin-top: 8px;">
      <summary style="cursor: pointer; font-size: 13px; font-weight: bold; color: #8B7355;">💬 Recruiter DM</summary>
      <p style="background: white; padding: 12px; border-radius: 4px; font-size: 13px; margin: 8px 0 0; line-height: 1.6;">${job.recruiter_dm}</p>
    </details>

    <a href="${job.url}" style="display: inline-block; margin-top: 12px; padding: 8px 16px; background: #8B7355; color: white; text-decoration: none; border-radius: 4px; font-size: 13px;">View Job →</a>
  </div>
`).join('');

const html = `
<div style="font-family: Georgia, serif; max-width: 680px; margin: 0 auto; padding: 32px; color: #1a1a1a;">

  <div style="border-bottom: 2px solid #8B7355; padding-bottom: 16px; margin-bottom: 24px;">
    <h1 style="font-size: 24px; margin: 0; color: #8B7355;">☀️ Good Morning, Jasmine</h1>
    <p style="margin: 4px 0 0; color: #666; font-size: 14px;">${today} · ${jobs.length} strong match${jobs.length !== 1 ? 'es' : ''} found</p>
  </div>

  ${jobCards}

  <div style="margin-top: 40px; padding: 20px; background: #f0ece4; border-radius: 8px; text-align: center;">
    <p style="margin: 0 0 4px; font-size: 13px; color: #555;">While you're job hunting, your next client might already be looking for you.</p>
    <a href="https://dynamackops.tiiny.site" style="font-size: 14px; font-weight: bold; color: #8B7355; text-decoration: none;">Dynamack Operations — AI Automation · App Builds · Brand Animation →</a>
  </div>

  <div style="margin-top: 24px; padding-top: 16px; border-top: 1px solid #eee; font-size: 11px; color: #999; text-align: center;">
    <p style="margin: 0;">Built by Jasmine Mack · Dynamack Operations LLC · Runs daily at 9am</p>
  </div>

</div>`;

const subject = `☀️ Job Digest ${today} — ${jobs.length} match${jobs.length !== 1 ? 'es' : ''} (top score: ${jobs[0].match_score}/10)`;

return [{ json: { html, subject } }];
